head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil40204";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — j

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil40204.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_ApplyJoin_onclick
 * @description 「가입신청」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ApplyJoin_onclick = async function(e){
    try {
        await scwin.applyJoin()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40204.btn_ApplyJoin_onclick' }); }
};

/**
 * @method
 * @name btn_GoURL_onclick
 * @description 「취소」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_GoURL_onclick = function(e){
    try {
        scwin.goURL('cancel')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40204.btn_GoURL_onclick' }); }
};

/**
 * @method
 * @name btn_addRegisterPersonal_r1_onclick
 * @description 「정보입력 추가」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_addRegisterPersonal_r1_onclick = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.addRegisterPersonal((String(((dma_pageContext.get("j") ?? "")) == null ? '' : ((dma_pageContext.get("j") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("j") ?? "")) == null ? '' : ((dma_pageContext.get("j") ?? "")))),selfVar)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40204.btn_addRegisterPersonal_r1_onclick' }); }
};

/**
 * @method
 * @name btn_addRegisterPersonal_2_r2_onclick
 * @description 「정보입력 추가」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_addRegisterPersonal_2_r2_onclick = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.addRegisterPersonal((String(((dma_pageContext.get("j") ?? "")) == null ? '' : ((dma_pageContext.get("j") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("j") ?? "")) == null ? '' : ((dma_pageContext.get("j") ?? "")))),selfVar)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40204.btn_addRegisterPersonal_2_r2_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_ApplyJoin
 * @description Apply Join 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ApplyJoin = async function () {
    const sbmOptions = {
        id: "tx_fn_ApplyJoin",
        method: "post",
        action: "/register/corpDiscls.do",
        ref: "dma_ApplyJoinReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name applyJoin
 * @description apply Join 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.applyJoin = async function () {
    const frm = (document.corpDisclsChrgForm || { elements: [] });
    const loopCnt = 3;
    for (let i = 0; i < loopCnt; i++) {
        if (i === 1) {
            if (dma_hiddenStore.get("isInputContents2") === "N") {
                continue;
            }
        } else {
            if (i === 2) {
                if (dma_hiddenStore.get("isInputContents3") === "N") {
                    continue;
                }
            }
        }
        if (!await scwin.chkForm(i)) {
            return;
        }
    }
    $c.util.getComponent('dma_ApplyJoinReq').set('method', 'registerCorpDisclsChrg');
    frm.action = 'corpDiscls.do';
    await scwin.tx_fn_ApplyJoin();
};

/**
 * @method
 * @name chkForm
 * @description chk Form 처리
 * @param {*} formNo formNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkForm = async function (formNo) {
    const frm = (document.corpDisclsChrgForm || { elements: [] });
    if (await scwin.checkRequired($c.util.getComponent(["ipt_chrgNm", "ipt_chrgNm_r1", "ipt_chrgNm_r2"][formNo]))) {
        return false;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "성명"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent(["ipt_chrgNm", "ipt_chrgNm_r1", "ipt_chrgNm_r2"][formNo]))) {
        return false;
    }
    if (await scwin.checkRequired($c.util.getComponent(["ipt_jobtitlNm", "ipt_jobtitlNm_r1", "ipt_jobtitlNm_r2"][formNo]))) {
        return false;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "성명"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent(["ipt_chrgNm", "ipt_chrgNm_r1", "ipt_chrgNm_r2"][formNo]))) {
        return false;
    }
    if (await scwin.checkRequired($c.util.getComponent(["ipt_depNm", "ipt_depNm_r1", "ipt_depNm_r2"][formNo]))) {
        return false;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "성명"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent(["ipt_chrgNm", "ipt_chrgNm_r1", "ipt_chrgNm_r2"][formNo]))) {
        return false;
    }
    if (await scwin.checkRequired($c.util.getComponent(["ipt_telNo1", "ipt_telNo1_r1", "ipt_telNo1_r2"][formNo])) || await scwin.checkRequired($c.util.getComponent(["ipt_telNo2", "ipt_telNo2_r1", "ipt_telNo2_r2"][formNo])) || await scwin.checkRequired($c.util.getComponent(["ipt_telNo3", "ipt_telNo3_r1", "ipt_telNo3_r2"][formNo]))) {
        return false;
    }
    if (!(scwin.isNumberInput($c.util.getComponent(["ipt_telNo1", "ipt_telNo1_r1", "ipt_telNo1_r2"][formNo])) && scwin.isNumberInput($c.util.getComponent(["ipt_telNo2", "ipt_telNo2_r1", "ipt_telNo2_r2"][formNo])) && scwin.isNumberInput($c.util.getComponent(["ipt_telNo3", "ipt_telNo3_r1", "ipt_telNo3_r2"][formNo])))) {
        await $c.win.alert('유선전화번호는 숫자만 입력하세요');
        return false;
    }
    if (!(scwin.isNumberInput($c.util.getComponent(["ipt_chrgInnrNo", "ipt_chrgInnrNo_r1", "ipt_chrgInnrNo_r2"][formNo])))) {
        await $c.win.alert('내선은 숫자만 입력하세요');
        return false;
    }
    if (await scwin.checkRequired($c.util.getComponent(["slc_cellphoneNo1", "slc_cellphoneNo1_r1", "slc_cellphoneNo1_r2"][formNo])) || await scwin.checkRequired($c.util.getComponent(["ipt_cellphoneNo2", "ipt_cellphoneNo2_r1", "ipt_cellphoneNo2_r2"][formNo])) || await scwin.checkRequired($c.util.getComponent(["ipt_cellphoneNo3", "ipt_cellphoneNo3_r1", "ipt_cellphoneNo3_r2"][formNo]))) {
        return false;
    }
    if (!(scwin.isNumberInput($c.util.getComponent(["slc_cellphoneNo1", "slc_cellphoneNo1_r1", "slc_cellphoneNo1_r2"][formNo])) && scwin.isNumberInput($c.util.getComponent(["ipt_cellphoneNo2", "ipt_cellphoneNo2_r1", "ipt_cellphoneNo2_r2"][formNo])) && scwin.isNumberInput($c.util.getComponent(["ipt_cellphoneNo3", "ipt_cellphoneNo3_r1", "ipt_cellphoneNo3_r2"][formNo])))) {
        await $c.win.alert('휴대전화번호는 숫자만 입력하세요');
        return false;
    }
    if (await scwin.checkRequired($c.util.getComponent(["ipt_faxNo1", "ipt_faxNo1_r1", "ipt_faxNo1_r2"][formNo])) || await scwin.checkRequired($c.util.getComponent(["ipt_faxNo2", "ipt_faxNo2_r1", "ipt_faxNo2_r2"][formNo])) || await scwin.checkRequired($c.util.getComponent(["ipt_faxNo3", "ipt_faxNo3_r1", "ipt_faxNo3_r2"][formNo]))) {
        return false;
    }
    if (!(scwin.isNumberInput($c.util.getComponent(["ipt_faxNo1", "ipt_faxNo1_r1", "ipt_faxNo1_r2"][formNo])) && scwin.isNumberInput($c.util.getComponent(["ipt_faxNo2", "ipt_faxNo2_r1", "ipt_faxNo2_r2"][formNo])) && scwin.isNumberInput($c.util.getComponent(["ipt_faxNo3", "ipt_faxNo3_r1", "ipt_faxNo3_r2"][formNo])))) {
        await $c.win.alert('FAX는 숫자만 입력하세요');
        return false;
    }
    if (await scwin.checkRequired($c.util.getComponent(["ipt_email1", "ipt_email1_r1", "ipt_email1_r2"][formNo])) || await scwin.checkRequired($c.util.getComponent(["ipt_email2", "ipt_email2_r1", "ipt_email2_r2"][formNo]))) {
        return false;
    }
    if (await scwin.checkRequired($c.util.getComponent(["ipt_chrgDesignYear", "ipt_chrgDesignYear_r1", "ipt_chrgDesignYear_r2"][formNo])) || await scwin.checkRequired($c.util.getComponent(["ipt_chrgDesignMonth", "ipt_chrgDesignMonth_r1", "ipt_chrgDesignMonth_r2"][formNo])) || await scwin.checkRequired($c.util.getComponent(["ipt_chrgDesignDay", "ipt_chrgDesignDay_r1", "ipt_chrgDesignDay_r2"][formNo]))) {
        return false;
    }
    if (!await scwin.checkDateParts($c.util.getComponent(["ipt_chrgDesignYear", "ipt_chrgDesignYear_r1", "ipt_chrgDesignYear_r2"][formNo]), $c.util.getComponent(["ipt_chrgDesignMonth", "ipt_chrgDesignMonth_r1", "ipt_chrgDesignMonth_r2"][formNo]), $c.util.getComponent(["ipt_chrgDesignDay", "ipt_chrgDesignDay_r1", "ipt_chrgDesignDay_r2"][formNo]), false)) {
        return false;
    }
    (console.warn("[sdd] unresolved:dmap-member:" + "telNo @ dma_ApplyJoinReq.telNo"), $c.util.getComponent('dma_ApplyJoinReq'))[formNo].value = $c.util.getComponent(["ipt_telNo1", "ipt_telNo1_r1", "ipt_telNo1_r2"][formNo]).getValue() + '-' + $c.util.getComponent(["ipt_telNo2", "ipt_telNo2_r1", "ipt_telNo2_r2"][formNo]).getValue() + '-' + $c.util.getComponent(["ipt_telNo3", "ipt_telNo3_r1", "ipt_telNo3_r2"][formNo]).getValue();
    (console.warn("[sdd] unresolved:dmap-member:" + "cellphoneNo @ dma_ApplyJoinReq.cellphoneNo"), $c.util.getComponent('dma_ApplyJoinReq'))[formNo].value = $c.util.getComponent(["slc_cellphoneNo1", "slc_cellphoneNo1_r1", "slc_cellphoneNo1_r2"][formNo]).getValue() + '-' + $c.util.getComponent(["ipt_cellphoneNo2", "ipt_cellphoneNo2_r1", "ipt_cellphoneNo2_r2"][formNo]).getValue() + '-' + $c.util.getComponent(["ipt_cellphoneNo3", "ipt_cellphoneNo3_r1", "ipt_cellphoneNo3_r2"][formNo]).getValue();
    (console.warn("[sdd] unresolved:dmap-member:" + "faxNo @ dma_ApplyJoinReq.faxNo"), $c.util.getComponent('dma_ApplyJoinReq'))[formNo].value = $c.util.getComponent(["ipt_faxNo1", "ipt_faxNo1_r1", "ipt_faxNo1_r2"][formNo]).getValue() + '-' + $c.util.getComponent(["ipt_faxNo2", "ipt_faxNo2_r1", "ipt_faxNo2_r2"][formNo]).getValue() + '-' + $c.util.getComponent(["ipt_faxNo3", "ipt_faxNo3_r1", "ipt_faxNo3_r2"][formNo]).getValue();
    (console.warn("[sdd] unresolved:dmap-member:" + "email @ dma_ApplyJoinReq.email"), $c.util.getComponent('dma_ApplyJoinReq'))[formNo].value = $c.str.trim($c.util.getComponent(["ipt_email1", "ipt_email1_r1", "ipt_email1_r2"][formNo]).getValue()) + '@' + $c.str.trim($c.util.getComponent(["ipt_email2", "ipt_email2_r1", "ipt_email2_r2"][formNo]).getValue());
    (console.warn("[sdd] unresolved:dmap-member:" + "chrgDesignDd @ dma_ApplyJoinReq.chrgDesignDd"), $c.util.getComponent('dma_ApplyJoinReq'))[formNo].value = $c.util.getComponent(["ipt_chrgDesignYear", "ipt_chrgDesignYear_r1", "ipt_chrgDesignYear_r2"][formNo]).getValue() + $c.util.getComponent(["ipt_chrgDesignMonth", "ipt_chrgDesignMonth_r1", "ipt_chrgDesignMonth_r2"][formNo]).getValue() + $c.util.getComponent(["ipt_chrgDesignDay", "ipt_chrgDesignDay_r1", "ipt_chrgDesignDay_r2"][formNo]).getValue();
    if (!$c.str.isEmail((console.warn("[sdd] unresolved:dmap-member:" + "email @ dma_ApplyJoinReq.email"), $c.util.getComponent('dma_ApplyJoinReq'))[formNo].value)) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name goURL
 * @description go URL 처리
 * @param {*} _target _target
 * @returns {void}
 * @hidden N
 */
scwin.goURL = function (_target) {
    let linkUrl;
    if (_target === 'cancel') {
        linkUrl = '/';
    }
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.setPageFrameSrc($c.win.getFrame(), (function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(linkUrl));
};

/**
 * @method
 * @name addRegisterPersonal
 * @description add Register Personal 처리
 * @param {*} number number
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.addRegisterPersonal = async function (number, obj) {
    const flag = $(obj).attr("flag");
    if (number === 2) {
        if (flag === "add") {
            $("#inputContents2").show();
            $(obj).attr("flag", "cancel");
            /* TODO Stage2: [sdd] 미실현 동작: set_label (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_label — {target}.setLabel({args}) */
            ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('isInputContents2', "Y") : console.warn('[sdd] hiddenStore 부재: isInputContents2'));
        } else {
            if (dma_hiddenStore.get("isInputContents3") === "Y") {
                await $c.win.alert("공시담당자2 정보가 입력 중인 상태에서 공시담당자1 정보입력을\n취소할 수 없습니다.");
                return;
            }
            if (await $c.win.confirm("공시담당자1의 입력한 정보가 삭제됩니다. 계속 하시겠습니까?")) {
                $("#inputContents2").hide();
                $(obj).attr("flag", "add");
                /* TODO Stage2: [sdd] 미실현 동작: set_label (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_label — {target}.setLabel({args}) */
                $("#inputContents2").find("input").val("");
                $("#inputContents2").find("select").each(function() {
                        $(this).val($(this).children("option").first().val());
                });
                ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('isInputContents2', "N") : console.warn('[sdd] hiddenStore 부재: isInputContents2'));
            }
        }
    } else {
        if (number === 3) {
            if (flag === "add") {
                $("#inputContents3").show();
                $(obj).attr("flag", "cancel");
                /* TODO Stage2: [sdd] 미실현 동작: set_label (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_label — {target}.setLabel({args}) */
                ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('isInputContents3', "Y") : console.warn('[sdd] hiddenStore 부재: isInputContents3'));
            } else {
                if (await $c.win.confirm("공시담당자2의 입력한 정보가 삭제됩니다. 계속 하시겠습니까?")) {
                    $("#inputContents3").hide();
                    $(obj).attr("flag", "add");
                    /* TODO Stage2: [sdd] 미실현 동작: set_label (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_label — {target}.setLabel({args}) */
                    $("#inputContents3").find("input").val("");
                    $("#inputContents3").find("select").each(function() {
                            $(this).val($(this).children("option").first().val());
                    });
                    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('isInputContents3', "N") : console.warn('[sdd] hiddenStore 부재: isInputContents3'));
                }
            }
        }
    }
};

/**
 * @method
 * @name checkPersonal
 * @description check Personal 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkPersonal = async function () {
    const personalChk = $c.util.getComponent('ipt_personalCheck').getValue();
    if (personalChk !== 'Y') {
        if (await $c.win.confirm("개인정보 처리방침 및 수집·이용에 동의해주시기 바랍니다.")) {
            (Promise.resolve($c.win.openPopup("/personalInfo_layer/personalInfo_layer.xml", { id: "personalInfo", width: "800", height: "700", scrollbars: false, type: "pageFramePopup" }, {})).then(function () {}), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("personalInfo"); this.closed = true; } });
        } else {
            return;
        }
    }
};

/**
 * @method
 * @name checkDateParts
 * @description 년·월·일 입력칸 3개로 나뉜 날짜 검사(as-is 공통 fn_CheckDateGn — 공백 제거·숫자·월/일 범위, 실패 시 알림+포커스)
 * @param {*} yyyy 년 입력 컴포넌트
 * @param {*} mm 월 입력 컴포넌트
 * @param {*} dd 일 입력 컴포넌트
 * @param {String} flag true 면 빈 값도 검사
 * @returns {Promise<Boolean>} 유효하면 true(빈 값·flag 없음이면 undefined — as-is 동일)
 * @hidden N
 */
scwin.checkDateParts = async function (yyyy, mm, dd, flag) {
    [yyyy, mm, dd].forEach(function (c) { c.setValue($c.str.trim(String(c.getValue() ?? ""))); });
    const ymd = yyyy.getValue() + mm.getValue() + dd.getValue();
    if (yyyy.getValue() === "" || yyyy.getValue().length < 4) { await $c.win.alert("년을 제대로 입력해주세요."); yyyy.focus(); return false; }
    if (ymd === "" && !flag) { return; }
    for (const c of [yyyy, mm, dd]) {
        if (!/^\d*$/.test(String(c.getValue()).replace(/\s/g, ""))) { await $c.win.alert("숫자만 입력하셔야 합니다."); c.focus(); return false; }
    }
    const year = Number(yyyy.getValue()), month = Number(mm.getValue()), day = Number(dd.getValue());
    if (month < 1 || month > 12) { await $c.win.alert("존재하지 않는 월입니다."); mm.focus(); return false; }
    if (year <= 0) { await $c.win.alert("존재하지 않는 년도입니다."); dd.focus(); return false; }
    if (day > new Date(year, month, 0).getDate()) { await $c.win.alert("존재하지 않는 날짜입니다."); dd.focus(); return false; }
    return true;
};

/**
 * @method
 * @name checkRequired
 * @description 필수 입력 검사 — 값이 비면 항목명으로 알리고 포커스를 준 뒤 true(as-is fn_NullChk/fn_IsNull 의미 보존 · pcc/fil 반입 후보)
 * @param {Object} comp 입력 컴포넌트
 * @param {*} fieldName 항목명(생략 시 컴포넌트 title → id)
 * @returns {Promise<Boolean>} 비어 있으면 true
 * @hidden N
 */
scwin.checkRequired = async function (comp, fieldName) {
    if (!comp || !$c.util.isEmpty($c.str.trim(String(comp.getValue() ?? "")))) { return false; }
    const name = fieldName || (typeof comp.getTitle === "function" && comp.getTitle()) || comp.getID();
    await $c.win.alert("'" + name + "' 항목을 입력하세요");
    comp.focus();
    return true;
};

/**
 * @method
 * @name isNumberInput
 * @description 숫자만 입력됐는지 검사 — 아니면 포커스를 주고 false(as-is fn_IsNumber 의미 보존 · pcc/fil 반입 후보)
 * @param {Object} comp 입력 컴포넌트
 * @returns {Boolean} 숫자(공백 제외)만이면 true
 * @hidden N
 */
scwin.isNumberInput = function (comp) {
    const v = String(comp.getValue() ?? "").replace(/\s/g, "");
    if (!/^\d*$/.test(v)) { comp.focus(); return false; }
    return true;
};
